  "target_production_order_item_id" bigint NOT NULL,
  "product_id" bigint NOT NULL,
  "product_sku_id" bigint NULL,
  "receiving_warehouse_id" bigint NOT NULL,
  "unit_id" bigint NOT NULL,
  "received_lot_id" bigint NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "rework_intake_items_quantity_positive" CHECK (quantity > (0)::numeric)
);
