-- Create "rework_intakes" table
CREATE TABLE "rework_intakes" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "intake_no" character varying NOT NULL,
  "customer_snapshot" character varying NOT NULL,
  "status" character varying NOT NULL DEFAULT 'DRAFT',
  "reason" character varying NOT NULL,
  "idempotency_key" character varying NOT NULL,
  "idempotency_payload_hash" character varying NOT NULL,
  "idempotency_item_count" bigint NOT NULL,
  "version" bigint NOT NULL DEFAULT 1,
  "received_at" timestamptz NULL,
  "received_by" bigint NULL,
  "cancelled_at" timestamptz NULL,
  "cancelled_by" bigint NULL,
  "cancel_reason" character varying NULL,
  "reversed_at" timestamptz NULL,
  "reversed_by" bigint NULL,
  "reverse_reason" character varying NULL,
  "created_by" bigint NOT NULL,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "source_shipment_id" bigint NOT NULL,
  "customer_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "rework_intakes_intent_bundle" CHECK (((length(TRIM(BOTH FROM idempotency_key)) >= 1) AND (length(TRIM(BOTH FROM idempotency_key)) <= 128)) AND (length((idempotency_payload_hash)::text) = 64) AND (idempotency_item_count > 0)),
  CONSTRAINT "rework_intakes_lifecycle_audit" CHECK ((((status)::text = 'DRAFT'::text) AND (received_at IS NULL) AND (received_by IS NULL) AND (cancelled_at IS NULL) AND (cancelled_by IS NULL) AND (cancel_reason IS NULL) AND (reversed_at IS NULL) AND (reversed_by IS NULL) AND (reverse_reason IS NULL)) OR (((status)::text = 'RECEIVED'::text) AND (received_at IS NOT NULL) AND (received_by IS NOT NULL) AND (cancelled_at IS NULL) AND (cancelled_by IS NULL) AND (cancel_reason IS NULL) AND (reversed_at IS NULL) AND (reversed_by IS NULL) AND (reverse_reason IS NULL)) OR (((status)::text = 'CANCELLED'::text) AND (received_at IS NULL) AND (received_by IS NULL) AND (cancelled_at IS NOT NULL) AND (cancelled_by IS NOT NULL) AND (cancel_reason IS NOT NULL) AND ((length(TRIM(BOTH FROM cancel_reason)) >= 1) AND (length(TRIM(BOTH FROM cancel_reason)) <= 255)) AND (reversed_at IS NULL) AND (reversed_by IS NULL) AND (reverse_reason IS NULL)) OR (((status)::text = 'REVERSED'::text) AND (received_at IS NOT NULL) AND (received_by IS NOT NULL) AND (cancelled_at IS NULL) AND (cancelled_by IS NULL) AND (cancel_reason IS NULL) AND (reversed_at IS NOT NULL) AND (reversed_by IS NOT NULL) AND (reverse_reason IS NOT NULL) AND ((length(TRIM(BOTH FROM reverse_reason)) >= 1) AND (length(TRIM(BOTH FROM reverse_reason)) <= 255)))),
  CONSTRAINT "rework_intakes_status_allowed" CHECK ((status)::text = ANY ((ARRAY['DRAFT'::character varying, 'RECEIVED'::character varying, 'CANCELLED'::character varying, 'REVERSED'::character varying])::text[])),
  CONSTRAINT "rework_intakes_version_positive" CHECK (version > 0)
);
